"""Self-contained report styles; shared by served and exported HTML reports."""

REPORT_CSS = """
:root{--ink:#294264;--muted:#70839e;--line:#dfe8f4;--paper:#fff;--bg:#f2f6fc;--accent:#326bc5;--red:#b54739;--amber:#946621;--green:#2f765e}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.9 "Microsoft YaHei UI","Microsoft YaHei","Segoe UI",sans-serif}
main{max-width:1080px;margin:30px auto;padding:32px 42px 45px;background:white;border:1px solid var(--line);border-radius:14px}
.eyebrow{display:flex;gap:10px;align-items:center;border-bottom:1px solid var(--line);padding-bottom:20px;margin-bottom:25px;color:#2c5794;font-size:22px;font-weight:700}.eyebrow span{font:12px "Segoe UI",sans-serif;color:#8296b2}
h1{font-size:28px;line-height:1.4;letter-spacing:-.5px;margin:0 0 14px}h2{display:flex;align-items:center;gap:10px;font-size:18px;margin:32px 0 15px;color:#355c8d;font-weight:650}h2:before{content:"";width:4px;height:17px;background:#5889d6;border-radius:3px}h3{font-size:15px;margin:0;color:#3c608e}h4{font-size:13px;margin:20px 0 9px;color:#6c87aa}
p{margin:10px 0}.meta,.muted,small{font-size:12px;color:var(--muted);line-height:1.9}.meta{overflow-wrap:anywhere}.summary{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:1px;margin:24px 0;background:var(--line);border:1px solid var(--line);border-radius:10px;overflow:hidden}.summary>div{grid-column:span 2;background:#f8fbff;padding:15px 18px}.summary>div:nth-child(2){grid-column:span 4}.summary small{display:block;margin-bottom:5px}.summary b{display:block;color:#446a9a;font-size:14px;font-weight:600;overflow-wrap:anywhere}
.notice{padding:15px 18px;border:1px solid #ecdfc8;border-radius:9px;background:#fffaf0;color:#92713e;font-size:12px;line-height:1.9}.notice>b{font-weight:600}.plan{margin:14px 0 22px;padding:23px;border:1px solid var(--line);border-radius:11px;background:white;break-inside:avoid}.plan>p{max-width:64em;color:#627c9c}.plan-head{display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:14px;border-bottom:1px solid #e6edf6;padding-bottom:16px;margin-bottom:16px}.plan-head h3{margin-bottom:5px}
.scores{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.score{position:relative;min-width:0;padding:20px;border:1px solid var(--line);border-radius:10px;background:#fbfcff;break-inside:avoid}.score:last-child:nth-child(odd){grid-column:1/-1}.score>small{display:block;font-size:13px;font-weight:600;color:#57769d}.score-number{display:inline-block;margin:9px 13px 9px 0;font-family:"Segoe UI",sans-serif;font-size:29px;font-weight:650;line-height:1.2;color:#456b9d}.score p{color:#7088a6;font-size:12px}.score-title{display:flex;align-items:center;gap:15px;flex-wrap:wrap;margin:17px 0 12px;font-size:22px}.score-title small{font-size:11px;font-weight:400}.score-details{border-top:1px solid var(--line);margin-top:14px;padding-top:10px}.score-details li{font-size:12px}
.pill{display:inline-flex;align-items:center;padding:4px 9px;border-radius:5px;background:#edf3fc;color:#4c75a9;font-size:11px;font-weight:600;vertical-align:middle}.pill.fail{background:#fff0eb;color:var(--red)}.pill.warning{background:#fff5df;color:var(--amber)}.pill.pass{background:#edf8f1;color:var(--green)}
.issue,.action{margin-top:13px;padding:17px 18px;border:1px solid #e2eaf6;border-left:3px solid #d2deef;border-radius:8px;background:#fafcff;break-inside:avoid}.action{border-color:#d8e5f8;border-left-color:#7b9fd3;background:#f2f7ff}.issue p,.action p{margin:8px 0;font-size:13px}.issue ul{margin-top:12px;padding-top:9px;border-top:1px solid #e3ebf5}.priority{display:inline-block;margin-right:8px;padding:2px 6px;border-radius:4px;font-size:11px;font-weight:600;color:var(--red);background:#fff0eb}
.time{display:inline-block;padding:2px 7px;border:1px solid #d6e4f6;border-radius:5px;background:#f0f6ff;color:#4b76b0;font-size:11px;font-weight:600;font-variant-numeric:tabular-nums}ul{padding-left:20px;margin:7px 0}li{margin:6px 0;overflow-wrap:anywhere}details{margin-top:16px;border:1px solid #e1e9f5;border-radius:8px;padding:13px 15px;background:#fbfcff}details>summary{color:#617fa6;font-size:12px;font-weight:500;cursor:pointer}details[open]>summary{margin-bottom:12px}table{max-width:100%;table-layout:fixed}th{color:#58769b;background:#f4f8fe;font-weight:600}td{color:#758ba7}footer{border-top:1px solid var(--line);margin-top:33px;padding-top:20px;color:var(--muted);font-size:12px}
@media(max-width:700px){main{margin:0;padding:24px 17px;border:0;border-radius:0}.summary{grid-template-columns:1fr 1fr}.summary>div,.summary>div:nth-child(2){grid-column:auto}.summary>div:nth-child(2){grid-column:1/-1;grid-row:1}.scores{grid-template-columns:1fr}.score:last-child:nth-child(odd){grid-column:auto}.plan{padding:17px}.score-title{font-size:20px}h1{font-size:25px}}
@media print{body{background:white}main{max-width:none;margin:0;border:0;border-radius:0;padding:0}.eyebrow{margin-bottom:20px}.scores{grid-template-columns:1fr 1fr}.plan,details,.score{box-shadow:none}.notice,.action,.issue{-webkit-print-color-adjust:exact;print-color-adjust:exact}details>summary{break-after:avoid}}
"""
